async function remove(id) {
  await fetch("/api/notes/" + id, { method: "DELETE" });
  UI.toast("Removed", "success");
  await load();
}

async function save(id, values) {
  const res = await fetch("/api/notes/" + id, {
    method: "PUT",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(values),
  });
  if (!res.ok) {
    UI.toast("Could not save", "error");
    return false;
  }
  UI.toast("Saved", "success");
  await load();
}

function fieldsOf(item) {
  return { title: item.title, content: item.content, tag: item.tag };
}

async function load() {
  UI.loading(list);
  const res = await fetch("/api/notes");
  const data = await res.json();
  let shown = data.items;
  const query = document.getElementById("search").value.toLowerCase();
  if (query) shown = shown.filter((i) => ["title", "content"].some((k) => String(i[k] ?? "").toLowerCase().includes(query)));
  count.textContent = shown.length + " " + "notes";
  UI.renderList(list, shown, (item) => ({
    title: "title",
    details: ["content"],
    badges: ["tag"],
    actions: [
      { label: "Edit", onClick: () => UI.form("Edit", FIELDS, item, (values) => save(item.id, values)) },
      { label: "Delete", kind: "danger", onClick: () => remove(item.id) },
    ],
  }), "Nothing here yet. Add the first one above.");
}

document.getElementById("form").addEventListener("submit", async (ev) => {
  ev.preventDefault();
  errorBox.textContent = "";
  const res = await fetch("/api/notes", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ title: document.getElementById("title").value, content: document.getElementById("content").value, tag: document.getElementById("tag").value }),
  });
  const data = await res.json();
  if (!res.ok) {
    errorBox.textContent = typeof data.detail === "string" ? data.detail : "Please check your input";
    return;
  }
  document.getElementById("form").reset();
  UI.toast("Added", "success");
  await load();
});
document.getElementById("search").addEventListener("input", load);

load();"}

